package org.slavicmyths.finist;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.syncher.*;import net.minecraft.resources.ResourceKey;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.*;import net.minecraft.world.item.*;import net.minecraft.world.effect.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;
/** Commander with exclusive cast clock; guards/banners belong to one UUID and are always bounded. */
public final class KartausEntity extends FalconActor {
 public UUID owner,encounter;public Vec3 center;public int phase=1;public boolean raged;private boolean dispelled;public final Set<UUID> banners=new HashSet<>(),guards=new HashSet<>();private final java.util.List<Vec3> guardPlan=new ArrayList<>();private UUID anchor;private long curseImmune;private LivingEntity committed;private Vec3 waveOrigin,waveDir;private boolean waveStopped;private final Set<UUID> waveHits=new HashSet<>();private final Map<UUID,Chain> chains=new HashMap<>();private int lastSkill,repeated,stuck;private long lastMove;private Vec3 lastPosition;
 private record Chain(Vec3 at,long until,int pulses){}
 private final ServerBossEvent bar=new ServerBossEvent(Component.translatable("entity.slavicmyths.kartaus"),BossEvent.BossBarColor.RED,BossEvent.BossBarOverlay.PROGRESS);
 private static final EntityDataAccessor<Integer> COUNT=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.INT),PHASE=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<BlockPos> GUARD1=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.BLOCK_POS),GUARD2=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.BLOCK_POS),GUARD3=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.BLOCK_POS);
 private static final EntityDataAccessor<Integer> GUARD_COUNT=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<BlockPos> AIM=SynchedEntityData.defineId(KartausEntity.class,EntityDataSerializers.BLOCK_POS);
 public KartausEntity(EntityType<? extends KartausEntity> t,Level w){super(t,w);center=position();}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(COUNT,0);b.define(PHASE,1);b.define(AIM,BlockPos.ZERO);b.define(GUARD1,BlockPos.ZERO);b.define(GUARD2,BlockPos.ZERO);b.define(GUARD3,BlockPos.ZERO);b.define(GUARD_COUNT,0);}
 public java.util.List<BlockPos> guardPositions(){var list=java.util.List.of(entityData.get(GUARD1),entityData.get(GUARD2),entityData.get(GUARD3));return list.subList(0,entityData.get(GUARD_COUNT));}
 public int bannerCount(){return entityData.get(COUNT);}public int syncedPhase(){return entityData.get(PHASE);}public BlockPos aim(){return entityData.get(AIM);}
 public boolean validEncounter(){return encounter==null||level() instanceof ServerLevel w&&KartausEncounter.get(w).active(encounter);}
 public FinistEntity hero(){if(!(level() instanceof ServerLevel w)||encounter==null)return null;var e=KartausEncounter.get(w).entries.get(encounter);return e!=null&&w.getEntity(e.hero) instanceof FinistEntity f?f:null;}
 public BannerEntity anchor(){return level() instanceof ServerLevel w&&anchor!=null&&w.getEntity(anchor) instanceof BannerEntity a?a:null;}
 public BannerEntity closestBanner(){return level() instanceof ServerLevel w?banners.stream().map(w::getEntity).filter(BannerEntity.class::isInstance).map(BannerEntity.class::cast).min(Comparator.comparingDouble(this::distanceToSqr)).orElse(null):null;}
 public float mitigation(){if(action()==FalconAction.STAGGER)return 0;int n=0;if(level() instanceof ServerLevel w)for(var id:banners)if(w.getEntity(id) instanceof BannerEntity a&&a.isAlive()&&distanceTo(a)<=11)n++;return Math.min(.4F,.1F+n*.15F);}
 public DamageSource source(String name){return new DamageSource(level().registryAccess().registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(ResourceKey.create(Registries.DAMAGE_TYPE,FinistContent.id("kartaus_"+name))),this);}
 public static float raw(float net){return (float)((-.2+Math.sqrt(.04+.04*net))/.02);}
 public void strike(LivingEntity t,String name,float net){if(t==null||!t.isAlive()||!hasLineOfSight(t))return;float damage=raw(net);if(phase==3&&(name.equals("wave")||name.equals("eye")))damage=raw(net*1.25F);t.hurt(source(name),damage);}
 public void cleanup(){if(!(level() instanceof ServerLevel w))return;for(var id:new ArrayList<>(banners)){var e=w.getEntity(id);if(e!=null)e.discard();}for(var id:new ArrayList<>(guards)){var e=w.getEntity(id);if(e!=null)e.discard();}var a=anchor();if(a!=null)a.discard();anchor=null;banners.clear();guards.clear();chains.clear();entityData.set(COUNT,0);var f=hero();if(f!=null)f.clearCurse();bar.removeAllPlayers();}
 public void releaseCurse(boolean rescued){var a=anchor();if(a!=null)a.discard();anchor=null;var f=hero();if(f!=null)f.clearCurse();curseImmune=level().getGameTime()+180;if(isAlive()){begin(FalconAction.STAGGER,rescued?50:20);cue("entity.falcon.chain_break");}}
 public void propGone(BannerEntity a,boolean destroyed){if(a.anchor()){releaseCurse(destroyed);return;}banners.remove(a.getUUID());entityData.set(COUNT,banners.size());if(banners.isEmpty()){cooldown("banner",160);begin(FalconAction.STAGGER,60);cue("entity.kartaus.barrier_break");}}
 private Vec3 propSpot(boolean curse){if(!(level() instanceof ServerLevel w))return null;for(int n=0;n<12;n++){double angle=(getYRot()+n*30)*Math.PI/180;var at=KartausEncounter.ground(w,position().add(Math.cos(angle)*(curse?5:7),0,Math.sin(angle)*(curse?5:7)),curse?.7:.85,curse?1:2);if(at==null||center.distanceToSqr(at)>17*17||getTarget()!=null&&at.distanceToSqr(getTarget().position())<16)continue;boolean close=banners.stream().map(w::getEntity).filter(Objects::nonNull).anyMatch(b->at.distanceToSqr(b.position())<25);if(!close)return at;}return null;}
 public boolean plant(){if(!(level() instanceof ServerLevel w)||banners.size()>=(phase==1?1:2))return false;var at=propSpot(false);if(at==null)return false;var a=FinistContent.BANNER.get().create(w);a.boss=getUUID();a.encounter=encounter;a.moveTo(at.x,at.y,at.z,getYRot(),0);if(!w.addFreshEntity(a))return false;banners.add(a.getUUID());entityData.set(COUNT,banners.size());return true;}
 public boolean bindFalcon(){var f=hero();if(!(level() instanceof ServerLevel w)||f==null||f.morphed()||f.recovering()||anchor()!=null||level().getGameTime()<curseImmune||phase<2)return false;var at=propSpot(true);if(at==null)return false;var a=FinistContent.ANCHOR.get().create(w);a.boss=getUUID();a.encounter=encounter;a.expiry=w.getGameTime()+240;a.moveTo(at.x,at.y,at.z,0,0);if(!w.addFreshEntity(a))return false;anchor=a.getUUID();f.curse(a);cue("entity.falcon.chained");return true;}
 private void planGuards(){guardPlan.clear();if(!(level() instanceof ServerLevel w)||getTarget()==null)return;int count=Math.min(3,phase==1?2:3)-guards.size();for(int n=0;n<12&&guardPlan.size()<count;n++){double a=n*Math.PI/6;var at=KartausEncounter.ground(w,position().add(Math.cos(a)*9,0,Math.sin(a)*9),.7,2.5);if(at!=null&&at.distanceToSqr(getTarget().position())>=25&&center.distanceToSqr(at)<=24*24)guardPlan.add(at);}var ids=java.util.List.of(GUARD1,GUARD2,GUARD3);entityData.set(GUARD_COUNT,guardPlan.size());for(int n=0;n<guardPlan.size();n++)entityData.set(ids.get(n),BlockPos.containing(guardPlan.get(n)));}
 public boolean guardBanner(Mob m){if(!(level() instanceof ServerLevel w))return false;for(var id:banners)if(w.getEntity(id) instanceof BannerEntity a&&a.isAlive()&&m.distanceTo(a)<=11)return true;return false;}
 public void summonGuards(){if(!(level() instanceof ServerLevel w)||getTarget()==null)return;if(guardPlan.isEmpty())planGuards();for(var at:new ArrayList<>(guardPlan)){if(guards.size()>=Math.min(3,phase==1?2:3)||!org.slavicmyths.skim.HeroCalls.safeSpot(w,at,.7,2.5))continue;var m=EntityType.WITHER_SKELETON.create(w);m.moveTo(at.x,at.y,at.z,0,0);m.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STONE_SWORD));m.setDropChance(EquipmentSlot.MAINHAND,0);m.setCanPickUpLoot(false);m.setPersistenceRequired();m.getPersistentData().putUUID("KartausBoss174",getUUID());if(encounter!=null)m.getPersistentData().putUUID("KartausEncounter174",encounter);m.targetSelector.removeAllGoals(g->true);m.goalSelector.removeAllGoals(g->g instanceof net.minecraft.world.entity.ai.goal.RangedBowAttackGoal||g instanceof net.minecraft.world.entity.ai.goal.MeleeAttackGoal);m.goalSelector.addGoal(2,new net.minecraft.world.entity.ai.goal.MeleeAttackGoal(m,1.1,false){@Override protected int getAttackInterval(){return guardBanner(m)?18:20;}});m.setTarget(getTarget());if(w.addFreshEntity(m))guards.add(m.getUUID());}guardPlan.clear();}

 private void cast(FalconAction a,String key,int cooldown){if(a.ordinal()==lastSkill)repeated++;else repeated=1;lastSkill=a.ordinal();committed=getTarget();if(committed!=null)face(committed);begin(a,phase==3?Math.max(a.ticks,a==FalconAction.GUARDS?50:a==FalconAction.CHAINS?47:0):a.ticks);cooldown(key,(int)Math.ceil(cooldown*(phase==3?.85:1)));
 String cue=switch(a){case BANNER->"banner_raise";case GUARDS->"summon_guard";case WAVE->"staff_wave";case CHAINS->"chain_bind";case EYE->"black_eye_charge";case CURSE->"curse_falcon";default->"staff_melee";};cue("entity.kartaus."+cue);
 if(a==FalconAction.GUARDS)planGuards();if(a==FalconAction.WAVE){waveOrigin=position();waveDir=heading();waveStopped=false;waveHits.clear();}if(a==FalconAction.CHAINS&&committed!=null)entityData.set(AIM,committed.blockPosition());}
 private void choose(){var t=getTarget();if(t==null)return;if(ready("banner")&&banners.size()<(phase==1?1:2)){cast(FalconAction.BANNER,"banner",260);return;}if(ready("guards")&&guards.size()<(phase==1?2:3)&&distanceTo(t)>5){cast(FalconAction.GUARDS,"guards",240);return;}if(phase>=2&&ready("curse")&&hero()!=null&&!hero().recovering()&&!hero().morphed()&&anchor()==null&&level().getGameTime()>=curseImmune){cast(FalconAction.CURSE,"curse",360);return;}
 var opts=new ArrayList<FalconAction>();if(ready("wave")&&distanceTo(t)<16)opts.add(FalconAction.WAVE);if(phase>=2&&ready("eye")&&distanceTo(t)<17)opts.add(FalconAction.EYE);if(ready("chains")&&distanceTo(t)<12)opts.add(FalconAction.CHAINS);if(ready("melee")&&edge(t)<3.3)opts.add(FalconAction.SWORD);if(opts.isEmpty())return;if(repeated>=2)opts.removeIf(a->a.ordinal()==lastSkill);if(opts.isEmpty())return;var a=opts.get(random.nextInt(opts.size()));String k=switch(a){case WAVE->"wave";case EYE->"eye";case CHAINS->"chains";default->"melee";};cast(a,k,switch(a){case WAVE->115;case EYE->220;case CHAINS->170;default->44;});if(a==FalconAction.SWORD)begin(a,24);}
 private List<LivingEntity> victims(double r){if(!(level() instanceof ServerLevel w))return List.of();var list=new ArrayList<LivingEntity>();if(getTarget()!=null&&distanceTo(getTarget())<=r)list.add(getTarget());var h=hero();if(h!=null&&!h.recovering()&&distanceTo(h)<=r&&!list.contains(h))list.add(h);return list;}
 private void wave(){if(waveStopped||age()<19||age()>32||waveOrigin==null)return;int n=age()-18;var last=waveOrigin.add(waveDir.scale(n-1)).add(0,.8,0);var next=waveOrigin.add(waveDir.scale(n)).add(0,.8,0);var hit=level().clip(new ClipContext(last,next,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,this));if(hit.getType()!=HitResult.Type.MISS){waveStopped=true;return;}for(var t:victims(18)){var d=t.position().subtract(waveOrigin);double along=d.dot(waveDir);double side=Math.abs(d.x*waveDir.z-d.z*waveDir.x);if(along>=n-1.5&&along<=n+.6&&side<=1.5&&Math.abs(d.y)<2&&waveHits.add(t.getUUID()))strike(t,"wave",6.5F);}}
 private void effect(){switch(action()){
 case BANNER->{if(frame(32))plant();}case GUARDS->{if(frame(25))summonGuards();}case CURSE->{if(frame(27))bindFalcon();}case WAVE->wave();
 case SWORD->{if(frame(13))for(var t:victims(4))if(cone(t,3.3,100)){strike(t,"melee",6);var d=t.position().subtract(position()).multiply(1,0,1).normalize();t.push(d.x*.55,.15,d.z*.55);}}
 case EYE->{if(frame(21)&&committed!=null)entityData.set(AIM,committed.blockPosition());if(frame(42)){var at=Vec3.atBottomCenterOf(aim());for(var t:victims(20))if(t.position().distanceToSqr(at)<2.5*2.5)strike(t,"eye",7);cue("entity.kartaus.black_eye_impact");if(phase==3&&hero()!=null&&!dispelled){dispelled=true;hero().dispel();}}}
 case CHAINS->{if(frame(22)&&committed!=null&&committed.position().distanceToSqr(Vec3.atBottomCenterOf(aim()))<2.5*2.5&&hasLineOfSight(committed)){strike(committed,"chains",2);committed.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,50,1));chains.put(committed.getUUID(),new Chain(committed.position(),level().getGameTime()+20,3));}}
 default->{} }
 }
 private void chainTicks(ServerLevel w){for(var item:new ArrayList<>(chains.entrySet())){var c=item.getValue();var t=w.getEntity(item.getKey());if(!(t instanceof LivingEntity l)||!l.isAlive()||l.position().distanceToSqr(c.at)>36){chains.remove(item.getKey());continue;}if(w.getGameTime()>=c.until){strike(l,"chains",1);if(c.pulses<=1)chains.remove(item.getKey());else chains.put(item.getKey(),new Chain(c.at,c.until+20,c.pulses-1));}}}
 @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel w))return;if(tickCount==1)cue("entity.kartaus.intro");if(!validEncounter()){cleanup();discard();return;}if(encounter==null&&tickCount==1){center=position();begin(FalconAction.INTRO);}
 if(encounter!=null){var p=w.getServer().getPlayerList().getPlayer(owner);if(p==null||!p.isAlive()||p.serverLevel()!=w||p.isSpectator()){var e=KartausEncounter.get(w).entries.get(encounter);if(e!=null)KartausEncounter.get(w).finish(w,e,false);return;}setTarget(p);}else if(tickCount%20==0)setTarget(w.getNearestPlayer(getX(),getY(),getZ(),24,p->p instanceof net.minecraft.world.entity.player.Player player&&player.isAlive()&&!player.isSpectator()&&!player.isCreative()));
 if(tickCount%20==0){banners.removeIf(id->!(w.getEntity(id) instanceof BannerEntity a)||!a.isAlive());guards.removeIf(id->!(w.getEntity(id) instanceof Monster m)||!m.isAlive());entityData.set(COUNT,banners.size());for(var id:guards){var m=(Monster)w.getEntity(id);if(m!=null){if(center.distanceToSqr(m.position())>24*24){m.discard();continue;}m.setTarget(getTarget());if(m.getPersistentData().getLong("FinistDistractedUntil")>w.getGameTime())m.setTarget(null);}}
 bar.setName(Component.translatable("entity.slavicmyths.kartaus").append(" — ").append(Component.translatable("message.slavicmyths.kartaus_banner_count",bannerCount())));bar.setProgress(Math.max(0,getHealth()/650));for(var p:w.players()){boolean visible=p.isAlive()&&!p.isSpectator()&&distanceTo(p)<36;if(visible)bar.addPlayer(p);else bar.removePlayer(p);}}
 chainTicks(w);if(tickCount%10==0&&anchor()!=null){var a=anchor();if(hero()==null||hero().recovering()||!HeroCallsSafe(a))releaseCurse(false);}int next=getHealth()<=195?3:getHealth()<=422.5?2:1;if(next>phase){phase=next;entityData.set(PHASE,phase);if(phase==3&&!raged){raged=true;begin(FalconAction.RAGE);cue("entity.kartaus.rage");}else begin(FalconAction.STAGGER,60);}
 if(action()!=FalconAction.IDLE){effect();if(age()>=duration()){if(action()==FalconAction.INTRO||action()==FalconAction.RAGE)begin(FalconAction.STAGGER,60);else begin(FalconAction.IDLE);}return;}
 if(getTarget()==null)return;if(distanceTo(getTarget())>36){getNavigation().stop();return;}if(tickCount%20==0)choose();if(action()==FalconAction.IDLE&&tickCount%10==0){if(distanceTo(getTarget())>13&&center.distanceToSqr(position())<24*24)getNavigation().moveTo(getTarget(),1);else getNavigation().stop();if(lastPosition!=null&&position().distanceToSqr(lastPosition)<.01&&distanceTo(getTarget())>13)stuck+=10;else stuck=0;lastPosition=position();if(stuck>100){getNavigation().moveTo(center.x,center.y,center.z,1);stuck=0;}}
 var v=getDeltaMovement();if(v.horizontalDistance()>.22)setDeltaMovement(v.multiply(.22/v.horizontalDistance(),1,.22/v.horizontalDistance()));}
 private boolean HeroCallsSafe(BannerEntity a){return org.slavicmyths.skim.HeroCalls.safeSpot((ServerLevel)level(),a.position(),.7,.95);}
 public void ownerDamage(DamageSource s){if(level() instanceof ServerLevel w&&encounter!=null&&s.getEntity() instanceof ServerPlayer p&&p.getUUID().equals(owner)&&!p.isCreative()&&!p.isSpectator()){var e=KartausEncounter.get(w).entries.get(encounter);if(e!=null){e.ownerHit=true;KartausEncounter.get(w).setDirty();}}}
 @Override protected net.minecraft.sounds.SoundEvent getHurtSound(DamageSource s){return FinistContent.sound("entity.kartaus.hurt_"+(1+random.nextInt(3)));}
 @Override protected void playStepSound(net.minecraft.core.BlockPos p,net.minecraft.world.level.block.state.BlockState state){if(!level().isClientSide)playSound(FinistContent.sound("entity.kartaus.heavy_step_"+(1+random.nextInt(2))),.3F,1);}
 @Override public void die(DamageSource s){ownerDamage(s);if(level() instanceof ServerLevel w&&encounter!=null){var e=KartausEncounter.get(w).entries.get(encounter);var p=owner==null?null:w.getServer().getPlayerList().getPlayer(owner);boolean eligible=e!=null&&e.ownerHit&&p!=null&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.serverLevel()==w&&p.position().distanceToSqr(center)<36*36&&!s.is(net.minecraft.world.damagesource.DamageTypes.GENERIC_KILL);if(e!=null)KartausEncounter.get(w).finish(w,e,eligible);}cleanup();begin(FalconAction.DEATH);cue("entity.kartaus.death");super.die(s);}
 @Override protected void tickDeath(){deathTime++;if(deathTime>=70){remove(RemovalReason.KILLED);}}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("KartausOwner",owner);if(encounter!=null)n.putUUID("KartausEncounter",encounter);n.putInt("KartausPhase",phase);n.putBoolean("KartausRaged",raged);n.putBoolean("KartausDispelled",dispelled);n.putDouble("CenterX",center.x);n.putDouble("CenterY",center.y);n.putDouble("CenterZ",center.z);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);owner=n.hasUUID("KartausOwner")?n.getUUID("KartausOwner"):null;encounter=n.hasUUID("KartausEncounter")?n.getUUID("KartausEncounter"):null;phase=Math.max(1,n.getInt("KartausPhase"));raged=n.getBoolean("KartausRaged");dispelled=n.getBoolean("KartausDispelled");center=new Vec3(n.getDouble("CenterX"),n.getDouble("CenterY"),n.getDouble("CenterZ"));entityData.set(PHASE,phase);/* Props/guards from disk are invalid without their tracked IDs, discarded on join. */}
}
